{
  "items": [
    {
      "name": "MvPolynomial.eval_toMvPolynomial",
      "type": " {R : Type u_1} {σ : Type u_3} [CommSemiring R] (f : σ → R) (i : σ) (p : Polynomial R) : (MvPolynomial.eval f) ((Polynomial.toMvPolynomial i) p) = Polynomial.eval (f i) p",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.optionEquivLeft_elim_eval",
      "type": " (R : Type u) (S₁ : Type v) [CommSemiring R] (s : S₁ → R) (y : R) (f : MvPolynomial (Option S₁) R) : (MvPolynomial.eval fun x => x.elim y s) f = Polynomial.eval y (Polynomial.map (MvPolynomial.eval s) ((MvPolynomial.optionEquivLeft R S₁) f))",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.eval_eq_eval_mv_eval'",
      "type": " {R : Type u} [CommSemiring R] {n : ℕ} (s : Fin n → R) (y : R) (f : MvPolynomial (Fin (n + 1)) R) : (MvPolynomial.eval (Fin.cons y s)) f = Polynomial.eval y (Polynomial.map (MvPolynomial.eval s) ((MvPolynomial.finSuccEquiv R n) f))",
      "module": "Mathlib.Algebra.MvPolynomial.Equiv"
    },
    {
      "name": "MvPolynomial.eval_polynomial_eval_finSuccEquiv",
      "type": " {R : Type u_1} {n : ℕ} {x : Fin n → R} [CommSemiring R] (f : MvPolynomial (Fin (n + 1)) R) (q : MvPolynomial (Fin n) R) : (MvPolynomial.eval x) (Polynomial.eval q ((MvPolynomial.finSuccEquiv R n) f)) = (MvPolynomial.eval fun i => Fin.cases ((MvPolynomial.eval x) q) x i) f",
      "module": "Mathlib.Algebra.MvPolynomial.Polynomial"
    },
    {
      "name": "Polynomial.eval_homogenize",
      "type": " {K : Type u_1} [Semifield K] {p : Polynomial K} {n : ℕ} (hn : p.natDegree ≤ n) (x : Fin 2 → K) (hx : x 1 ≠ 0) : (MvPolynomial.eval x) (p.homogenize n) = Polynomial.eval (x 0 / x 1) p * x 1 ^ n",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    },
    {
      "name": "Polynomial.eval_eq_div_eval_toTupleMvPolynomial",
      "type": " {R : Type u_2} [Field R] (p : Polynomial R) (x : R) : Polynomial.eval x p = (MvPolynomial.eval ![x, 1]) (p.toTupleMvPolynomial 0) / (MvPolynomial.eval ![x, 1]) (p.toTupleMvPolynomial 1)",
      "module": "Mathlib.Algebra.Polynomial.Homogenize"
    }
  ]
}
